head.script:
//
(function () {
  var XHTML_NS = "http://www.w3.org/1999/xhtml";
  var fo = document.querySelector("foreignObject");
  var root = fo && fo.firstElementChild;
  if (!root) return;
  var originalCreateElement = document.createElement.bind(document);
  var originalCreateElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, "head", {
    get: function () { return root.querySelector("head"); },
    configurable: true
  });
  Object.defineProperty(document, "body", {
    get: function () { return root.querySelector("body"); },
    configurable: true
  });
  Object.defineProperty(document, "documentElement", {
    get: function () { return root; },
    configurable: true
  });
  document.createElement = function (tagName, options) {
    if (typeof tagName === "string") {
      return originalCreateElementNS(XHTML_NS, tagName, options);
    }
    return originalCreateElement(tagName, options);
  };
  document.createElementNS = function (namespaceURI, qualifiedName, options) {
    if (namespaceURI == null || namespaceURI === XHTML_NS) {
      return originalCreateElementNS(XHTML_NS, qualifiedName, options);
    }
    return originalCreateElementNS(namespaceURI, qualifiedName, options);
  };
})();
//

//
(async function () {
  var boot = document.getElementById("boot");
  function status(t) {
    if (boot) boot.innerHTML = t;
    try { console.log("[macos-svg]", t.replace(/<[^>]+>/g, " ")); } catch (e) {}
  }

  // Same-folder index.html (OpiumBest/svg style on jsDelivr)
  var pageUrl = new URL("index.html", location.href).href;
  var baseHref = new URL(".", location.href).href;
  status("Fetching Mac OS…<br><small>" + pageUrl + "</small>");

  var html;
  try {
    var res = await fetch(pageUrl, { cache: "no-store", mode: "cors" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    html = await res.text();
    if (!html || html.length < 500) throw new Error("index.html too small (" + (html && html.length) + " bytes)");
  } catch (err) {
    status(
      "Could not fetch index.html.<br>" +
      ((err && err.message) || err) +
      "<br><br>Put <b>index.html</b> next to this SVG in the repo, then open:<br>" +
      "<a href=\"" + pageUrl + "\">" + pageUrl + "</a>"
    );
    return;
  }

  status("Preparing document (" + Math.round(html.length / 1024) + " KB)…");

  // Inject <base> so relative URLs work
  if (!/<base\s/i.test(html)) {
    html = html.replace(/<head([^>]*)>/i, function (m, a) {
      return "<head" + a + ">\n<base href=\"" + baseHref + "\">";
    });
  }

  // Flag for the page: we are under the SVG URL (good for SW path)
  html = html.replace(/<head([^>]*)>/i, function (m, a) {
    return "<head" + a + ">\n<script>window.__NYX_SVG_PARENT=\"" +
      location.href.replace(/"/g, "") + "\";<\/script>";
  });

  /*
    Use srcdoc iframe: inherits parent origin (cdn.jsdelivr.net)
    and renders as HTML (unlike jsDelivr's text/plain for .html).
    Parent location stays …/index.svg so SW can be …/sw.js.
  */
  try {
    var iframe = document.createElement("iframe");
    iframe.className = "mac";
    iframe.setAttribute("allow", "fullscreen; autoplay; encrypted-media; clipboard-read; clipboard-write");

    // Prefer blob URL — handles large HTML better than srcdoc on some browsers
    var blob = new Blob([html], { type: "text/html;charset=utf-8" });
    var blobUrl = URL.createObjectURL(blob);
    iframe.src = blobUrl;

    document.body.appendChild(iframe);
    if (boot) boot.style.display = "none";
    console.log("[macos-svg] mounted blob iframe, parent=", location.href, "bytes=", html.length);

    // Safety: if still blank after 8s, show link
    setTimeout(function () {
      try {
        if (boot && boot.style.display === "none") return;
      } catch (e) {}
    }, 8000);
  } catch (err2) {
    status(
      "Mount failed: " + ((err2 && err2.message) || err2) +
      "<br><br><a href="" + pageUrl + "" target="_blank">Open index.html</a> " +
      "(on jsDelivr it may show as text — prefer the SVG entry.)"
    );
  }
})();
//
